import{_ as r,o as d,c as o,a2 as e}from"./chunks/framework.B-bxTAy7.js";const g=JSON.parse('{"title":"NVIC 优先级","description":"抢占优先级与子优先级的分工、优先级分组的位数分配，以及数值越小越优先的规则。","frontmatter":{"title":"NVIC 优先级","description":"抢占优先级与子优先级的分工、优先级分组的位数分配，以及数值越小越优先的规则。"},"headers":[],"relativePath":"prereq/nvic-priority.md","filePath":"prereq/nvic-priority.md","lastUpdated":null}'),i={name:"prereq/nvic-priority.md"};function a(n,t,l,s,c,h){return d(),o("div",null,[...t[0]||(t[0]=[e('<h1 id="nvic-优先级" tabindex="-1">NVIC 优先级 <a class="header-anchor" href="#nvic-优先级" aria-label="Permalink to &quot;NVIC 优先级&quot;">​</a></h1><h2 id="结论先行" tabindex="-1">结论先行 <a class="header-anchor" href="#结论先行" aria-label="Permalink to &quot;结论先行&quot;">​</a></h2><ul><li>Cortex-M 的 NVIC 管理所有中断，用<strong>优先级分组</strong>决定 4 位优先级如何拆成「抢占位」与「子位」。</li><li><strong>抢占优先级决定能不能嵌套</strong>：只有抢占优先级数值<strong>更小</strong>（更高）的中断才能打断正在执行的 ISR。</li><li><strong>子优先级只决定排队顺序</strong>：多个中断同时挂起时，子优先级高的先执行；它<strong>永远不会造成嵌套</strong>。</li><li><strong>数值越小优先级越高</strong>（0 最高）。这和很多 RTOS 里「任务优先级数字越大越优先」的习惯相反，极易记反。</li><li>整个系统<strong>只用一种分组</strong>；改分组会让所有已设优先级的含义改变。</li></ul><p><strong>为什么它承重</strong>：优先级配错的后果分两种极端——全都设成同一级，系统失去实时性保证；某个关键中断设得太高，它会把所有别的中断都挡在门外。两者都会在「偶发丢帧、偶发卡死」里现形。</p><h2 id="典型数值" tabindex="-1">典型数值 <a class="header-anchor" href="#典型数值" aria-label="Permalink to &quot;典型数值&quot;">​</a></h2><p>Cortex-M 用 4 位表示优先级（STM32 实际只用高 4 位）：</p><table tabindex="0"><thead><tr><th>分组</th><th>抢占位数</th><th>抢占级数</th><th>子优先级位数</th><th>子级数</th></tr></thead><tbody><tr><td>0</td><td>0</td><td>1 级</td><td>4</td><td>16 级</td></tr><tr><td>1</td><td>1</td><td>2 级</td><td>3</td><td>8 级</td></tr><tr><td>2</td><td>2</td><td>4 级</td><td>4 级</td><td>4 级</td></tr><tr><td><strong>3</strong></td><td>3</td><td>8 级</td><td>1</td><td>2 级</td></tr><tr><td>4</td><td>4</td><td>16 级</td><td>0</td><td>1 级</td></tr></tbody></table><ul><li>典型选择：<strong>分组 3</strong>（3 位抢占 + 1 位子）。抢占级数留足余量，将来加中断不用改分组；子优先级够用来排「同时挂起」的队。</li><li>STM32 里抢占优先级是 <code>HAL_NVIC_SetPriority(IRQn, PreemptPriority, SubPriority)</code> 的第一个参数。</li></ul><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li><strong>把优先级数值记反</strong>：0 是最高，不是最低。</li><li><strong>以为子优先级也能嵌套</strong>：抢占相同则只能排队，子优先级再高也不能插队。</li><li>改了分组却没重新设置所有中断的优先级：旧的数值在新分组下含义全变。</li><li>忘了 <code>HAL_NVIC_EnableIRQ</code>：优先级设得再对，中断也不会进来。</li><li>把 SysTick 的优先级设得比用户中断低（数值更大）：在 ISR 里调 <code>HAL_Delay</code> 会死等 <code>uwTick</code>，程序彻底卡死。</li></ul><div class="tip custom-block" id="ex-nvic-priority-1"><p class="custom-block-title">例 1 · 判断会不会嵌套</p><p>设分组 2（4 级抢占），三种情形：</p><table tabindex="0"><thead><tr><th>情形</th><th>结果</th></tr></thead><tbody><tr><td>A 抢占 = 1 正在执行，B 抢占 = 0 到来</td><td><strong>B 抢占 A</strong>（0 &lt; 1），A 暂停，B 执行完 A 继续</td></tr><tr><td>A 抢占 = 1 正在执行，B 抢占 = 2 到来</td><td><strong>B 不能打断</strong>，等 A 执行完后才执行</td></tr><tr><td>A 抢占 = 1、子 = 0；B 抢占 = 1、子 = 1；A 正在执行</td><td><strong>不嵌套</strong>，B 排队</td></tr></tbody></table><p>第三种最容易被误解：以为「子优先级高」就能插队打断。记住一句话：<strong>抢占管打断，子优先级管排队</strong>。</p><blockquote><p><strong>为什么这么想</strong> 把优先级想成「门牌号」：抢占是「能不能进门」，子优先级是「门开着时谁先进」。门本身锁着的时候（正在执行同抢占级的中断），门牌再小也没用。</p></blockquote></div><blockquote><p>深入：完整内容见 <a href="./../embedded/interrupt">06 · 中断与 NVIC</a></p></blockquote>',12)])])}const u=r(i,[["render",a]]);export{g as __pageData,u as default};
